{
  "name": "opencode-auto-approval-plugin",
  "version": "0.13.3",
  "description": "opencode plugin that auto-approves tool permission requests based on configurable rules",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "permission",
    "auto-approval",
    "typescript"
  ],
  "homepage": "https://github.com/dyoshikawa/opencode-auto-approval-plugin#readme",
  "bugs": {
    "url": "https://github.com/dyoshikawa/opencode-auto-approval-plugin/issues"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/dyoshikawa/opencode-auto-approval-plugin.git"
  },
  "license": "MIT",
  "author": "dyoshikawa",
  "type": "module",
  "exports": {
    ".": {
      "import": {
        "types": "./dist/index.d.ts",
        "default": "./dist/index.js"
      },
      "require": {
        "types": "./dist/index.d.cts",
        "default": "./dist/index.cjs"
      }
    }
  },
  "main": "dist/index.cjs",
  "module": "dist/index.js",
  "types": "dist/index.d.ts",
  "bin": {
    "opencode-auto-approval-plugin": "dist/bin.js"
  },
  "files": [
    "dist"
  ],
  "simple-git-hooks": {
    "pre-commit": "pnpm exec lint-staged"
  },
  "dependencies": {
    "zod": "4.6.7"
  },
  "devDependencies": {
    "@anthropic-ai/claude-agent-sdk": "0.3.312",
    "@openai/codex-sdk": "0.165.0",
    "@opencode-ai/plugin": "1.19.4",
    "@opencode/plugin": "2.2.0",
    "@secretlint/secretlint-rule-preset-recommend": "13.1.0",
    "@tsconfig/node22": "22.0.6",
    "@types/node": "26.6.5",
    "@vitest/coverage-v8": "5.0.5",
    "cspell": "10.4.0",
    "knip": "6.43.0",
    "lint-staged": "17.6.0",
    "oxfmt": "0.75.0",
    "oxlint": "1.90.0",
    "rulesync": "43.2.0",
    "secretlint": "13.1.0",
    "simple-git-hooks": "2.14.0",
    "sort-package-json": "4.1.0",
    "tsdown": "0.23.3",
    "tsx": "4.23.15",
    "typescript": "7.0.2",
    "vitest": "5.0.5"
  },
  "peerDependencies": {
    "@anthropic-ai/claude-agent-sdk": ">=0.3.0 <1",
    "@openai/codex-sdk": ">=0.163.0 <1",
    "@opencode-ai/plugin": ">=1.18.29 <2",
    "@opencode/plugin": ">=2.0.0 <3"
  },
  "peerDependenciesMeta": {
    "@anthropic-ai/claude-agent-sdk": {
      "optional": true
    },
    "@openai/codex-sdk": {
      "optional": true
    },
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    }
  },
  "engines": {
    "node": ">=22.0.0",
    "pnpm": ">=10"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsdown",
    "check": "pnpm run fmt:check && pnpm run oxlint && pnpm run typecheck",
    "cicheck": "pnpm run cicheck:code && pnpm run cicheck:content",
    "cicheck:code": "pnpm run check && pnpm run test",
    "cicheck:content": "pnpm run cspell && pnpm run secretlint",
    "cspell": "cspell --no-progress --gitignore .",
    "fix": "pnpm run fmt && pnpm run oxlint:fix",
    "fmt": "oxfmt .",
    "fmt:check": "oxfmt --check .",
    "generate": "rulesync generate",
    "knip": "knip",
    "oxlint": "oxlint . --max-warnings 0",
    "oxlint:fix": "oxlint . --fix --max-warnings 0",
    "secretlint": "secretlint --secretlintignore .gitignore \"**/*\"",
    "sort": "sort-package-json",
    "test": "vitest run --silent=true",
    "test:coverage": "vitest run --coverage --silent=true",
    "test:watch": "vitest --silent=true",
    "typecheck": "tsc --noEmit"
  }
}
